    #define _NSETMASK_(msb, lsb)   (_bSETMASK_((msb) + 1) - _bSETMASK_(lsb))
    #define _bCLRMASK_(b)          (~_bSETMASK_(b))
    #define _NCLRMASK_(msb, lsb)   (~_NSETMASK_(msb, lsb))
    #define _BFGET_(r, msb, lsb)   (_NSETMASK_((msb) - (lsb), 0) & ((r) >> (lsb)))
